def rect(x0,y0,x1,y1):return [[x0,y0],[x1,y0],[x1,y1],[x0,y1]]
def area(poly):return abs(sum(a[0]*c[1]-c[0]*a[1] for a,c in zip(poly,poly[1:]+poly[:1])))/2 if poly else None
def ev(floor,handles,desc):return {'floor':floor,'handles':handles,'description':desc}
def zone(id,name,floor,polygon,status,elevation=None,structural=None,sources=[],**kw):return dict(id=id,name=name,floor=floor,polygon=polygon,areaM2=round(area(polygon),3) if polygon else None,status=status,elevation=elevation,structuralElevation=structural,source=sources,**kw)
